<?php require_once __DIR__.'/../includes/config.php';require_admin();$id=(int)($_GET['id']??0);$item=['title'=>'','description'=>'','category'=>'FREE','poster_url'=>'','playlist_url'=>''];if($id){$q=db()->prepare('SELECT * FROM playlists WHERE id=?');$q->execute([$id]);$item=$q->fetch()?:redirect('/admin/');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$item=array_merge($item,['title'=>trim($_POST['title']),'description'=>trim($_POST['description']),'category'=>$_POST['category']??'FREE','poster_url'=>trim($_POST['poster_url']),'playlist_url'=>trim($_POST['playlist_url'])]);if(!$item['title']||!$item['description']||!filter_var($item['poster_url'],FILTER_VALIDATE_URL)||!in_array($item['category'],['FREE','VIP'],true)){$error='Заполните обязательные поля и укажите корректную ссылку на постер.';}else{$fileName=$item['file_path']??null;if(!empty($_FILES['playlist_file']['name'])){if($_FILES['playlist_file']['error']!==UPLOAD_ERR_OK||pathinfo($_FILES['playlist_file']['name'],PATHINFO_EXTENSION)!=='m3u'){$error='Можно загрузить только файл .m3u';}else{if(!is_dir(PLAYLIST_STORAGE))mkdir(PLAYLIST_STORAGE,0755,true);$fileName=bin2hex(random_bytes(16)).'.m3u';move_uploaded_file($_FILES['playlist_file']['tmp_name'],PLAYLIST_STORAGE.'/'.$fileName);}}if(!$error){if($id){$q=db()->prepare('UPDATE playlists SET title=?,description=?,category=?,poster_url=?,playlist_url=?,file_path=? WHERE id=?');$q->execute([$item['title'],$item['description'],$item['category'],$item['poster_url'],$item['playlist_url']?:null,$fileName,$id]);}else{$q=db()->prepare('INSERT INTO playlists(title,description,category,poster_url,playlist_url,file_path) VALUES(?,?,?,?,?,?)');$q->execute([$item['title'],$item['description'],$item['category'],$item['poster_url'],$item['playlist_url']?:null,$fileName]);}redirect('/admin/');}}}$title=($id?'Редактировать':'Добавить').' · '.APP_NAME;require __DIR__.'/../includes/header.php';?><section class="auth"><form method="post" enctype="multipart/form-data" class="panel wide-panel"><p class="eyebrow">АДМИН-ПАНЕЛЬ</p><h1><?=$id?'Редактировать плейлист':'Новый плейлист'?></h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Название<input name="title" value="<?=e($item['title'])?>" required></label><label>Описание<textarea name="description" required><?=e($item['description'])?></textarea></label><label>Категория<select name="category"><option <?=$item['category']==='FREE'?'selected':''?>>FREE</option><option <?=$item['category']==='VIP'?'selected':''?>>VIP</option></select></label><label>Ссылка на постер (16:9)<input type="url" name="poster_url" value="<?=e($item['poster_url'])?>" required></label><label>Ссылка на плейлист<input type="url" name="playlist_url" value="<?=e($item['playlist_url'])?>"></label><label>Файл плейлиста .m3u <small>(необязательно)</small><input type="file" name="playlist_file" accept=".m3u,audio/x-mpegurl"></label><button class="button wide">Сохранить</button></form></section><?php require __DIR__.'/../includes/footer.php';?>
